def maxDistance(words):
    n = len(words)
    # If first and last are unequal, that pair gives the largest possible distance n
    if words[0] != words[-1]:
        return n

    best = 0
    # Farthest j from the left end with words[j] != words[0]: distance j - 0 + 1
    for j in range(n - 1, -1, -1):
        if words[j] != words[0]:
            best = max(best, j + 1)
            break

    # Farthest-left i with words[i] != words[-1]: distance (n-1) - i + 1
    for i in range(n):
        if words[i] != words[-1]:
            best = max(best, n - i)
            break

    return best
